-- Synthetic identities only. The caller wraps SET LOCAL ROLE service_role / ROLLBACK.
do $test$
declare
 admin_token text:=encode(sha256(convert_to(gen_random_uuid()::text,'UTF8')),'hex');
 staff_token text:=encode(sha256(convert_to(gen_random_uuid()::text,'UTF8')),'hex');
 other_token text:=encode(sha256(convert_to(gen_random_uuid()::text,'UTF8')),'hex');
 staff uuid:=gen_random_uuid();other_staff uuid:=gen_random_uuid();
 request_one uuid:=gen_random_uuid();sample_one uuid:=gen_random_uuid();
 r jsonb; r2 jsonb; consent_payload jsonb; fix_payload jsonb; original_expiry timestamptz; family uuid;
begin
 insert into navrang_private.checkers(id,name,method,active,name_confirmed,scanner_enabled,selected_station)
 values(staff,'Synthetic located volunteer','code',true,true,true,'checker'),(other_staff,'Synthetic other volunteer','code',true,true,true,'checker');
 insert into navrang_private.sessions(hash,role,checker_id,expires_at) values(admin_token,'admin',null,clock_timestamp()+interval '1 hour'),(staff_token,'checker',staff,clock_timestamp()+interval '1 hour'),(other_token,'checker',other_staff,clock_timestamp()+interval '1 hour');
 r:=public.navrang_locator('locator-status','{"eventId":"O9KL3"}',staff_token);
 if not r ? 'serverTime' or (r->>'serverTime')::timestamptz>clock_timestamp()+interval '1 second' then raise exception 'Locator deadline lacks an authoritative server clock';end if;
 if r->>'location'<>'false' or r->>'findMe'<>'false' or r->>'disclosureVersion'<>'0' or r->>'onDuty'<>'false' then raise exception 'Locator did not default off';end if;
 r:=public.navrang_locator('locator-roster','{"eventId":"O9KL3"}',admin_token);
 if r->>'status'<>'403' then raise exception 'Unassigned administrator accessed locator';end if;
 insert into navrang_private.locator_event_admins(event_id,principal,display_name) values('O9KL3','admin','Namdev') on conflict(event_id,principal) do update set display_name='Namdev';
 r:=public.navrang_locator('locator-duty',jsonb_build_object('eventId','O9KL3','requestId',gen_random_uuid(),'durationMinutes',60),staff_token);
 if r->>'status'<>'409' then raise exception 'Duty started without consent';end if;
 consent_payload:=jsonb_build_object('eventId','O9KL3','requestId',gen_random_uuid(),'disclosureVersion',1,'location',true,'findMe',true);
 r:=public.navrang_locator('locator-consent',consent_payload,staff_token);
 r2:=public.navrang_locator('locator-consent',consent_payload,staff_token);
 if r2->>'version'<>r->>'version' then raise exception 'Consent replay changed version';end if;
 r:=public.navrang_locator('locator-duty',jsonb_build_object('eventId','O9KL3','requestId',gen_random_uuid(),'durationMinutes',60),staff_token);
 if r->>'onDuty'<>'true' or (r->>'expiresAt')::timestamptz>clock_timestamp()+interval '1 hour 1 second' then raise exception 'Duty duration invalid';end if;
 r:=public.navrang_locator('locator-request',jsonb_build_object('eventId','O9KL3','requestId',request_one,'volunteerId',staff),admin_token);
 if r->>'delivery'<>'queued' or r->>'administrator'<>'Namdev' then raise exception 'Request invented delivery or trusted administrator';end if;
 original_expiry:=(r->>'expiresAt')::timestamptz;
 r2:=public.navrang_locator('locator-request',jsonb_build_object('eventId','O9KL3','requestId',request_one,'volunteerId',staff),admin_token);
 if (r2->>'expiresAt')::timestamptz<>original_expiry then raise exception 'Request replay extended expiry';end if;
 r:=public.navrang_locator('locator-request',jsonb_build_object('eventId','O9KL3','requestId',gen_random_uuid(),'volunteerId',staff),admin_token);
 if r->>'status'<>'429' then raise exception 'Target cooldown bypassed';end if;
 r:=public.navrang_locator('locator-inbox','{"eventId":"O9KL3"}',other_token);
 if r->'items'<>'[]'::jsonb then raise exception 'Other volunteer saw private request';end if;
 r:=public.navrang_locator('locator-roster','{"eventId":"O9KL3"}',staff_token);
 if r->>'status'<>'403' then raise exception 'Volunteer saw roster';end if;
 r:=public.navrang_locator('locator-respond',jsonb_build_object('eventId','O9KL3','requestId',request_one,'choice','sound'),other_token);
 if r->>'status'<>'404' then raise exception 'Other volunteer acted on request';end if;
 r:=public.navrang_locator('locator-respond',jsonb_build_object('eventId','O9KL3','requestId',request_one,'choice','acknowledged'),staff_token);
 if r->>'state'<>'device-acknowledged' then raise exception 'Acknowledgement was not distinct';end if;
 r:=public.navrang_locator('locator-respond',jsonb_build_object('eventId','O9KL3','requestId',request_one,'choice','sound'),staff_token);
 r2:=public.navrang_locator('locator-respond',jsonb_build_object('eventId','O9KL3','requestId',request_one,'choice','sound'),staff_token);
 if r->>'performAction'<>'true' or r2->>'performAction'<>'false' then raise exception 'Sound replay accepted twice';end if;
 fix_payload:=jsonb_build_object('eventId','O9KL3','sampleId',sample_one,'requestId',request_one,'latitude',15.49,'longitude',73.82,'accuracy',35,'capturedAt',clock_timestamp());
 r:=public.navrang_locator('locator-fix',fix_payload,staff_token);
 if r->>'saved'<>'true' then raise exception 'Explicit own fix failed: %',r;end if;
 r:=public.navrang_locator('locator-fix',fix_payload||jsonb_build_object('latitude',16),staff_token);
 if r->>'duplicate'<>'true' or (select latitude from navrang_private.locator_fixes where checker_id=staff)<>15.49 then raise exception 'Sample replay changed coordinates';end if;
 r:=public.navrang_locator('locator-roster','{"eventId":"O9KL3"}',admin_token);
 if jsonb_array_length(r->'items')<>1 or r->'items'->0 ? 'fix' then raise exception 'Roster leaked coordinates or omitted active volunteer';end if;
 r:=public.navrang_locator('locator-view',jsonb_build_object('eventId','O9KL3','volunteerId',staff),admin_token);
 if r->'fix'->>'accuracy'<>'35' then raise exception 'Authorized selected-person latest fix unavailable';end if;
 r:=public.navrang_locator('locator-fix',fix_payload||jsonb_build_object('sampleId',gen_random_uuid(),'capturedAt',clock_timestamp()-interval '31 seconds'),staff_token);
 if r->>'status'<>'400' then raise exception 'Stale fix accepted';end if;
 r:=public.navrang_locator('locator-fix',fix_payload||jsonb_build_object('sampleId',gen_random_uuid(),'latitude',91),staff_token);
 if r->>'status'<>'400' then raise exception 'Invalid coordinate accepted';end if;
 r:=public.navrang_locator('locator-found',jsonb_build_object('eventId','O9KL3','requestId',request_one),staff_token);
 if r->>'status'<>'403' then raise exception 'Volunteer declared administrator found';end if;
 r:=public.navrang_locator('locator-found',jsonb_build_object('eventId','O9KL3','requestId',request_one),admin_token);
 if r->>'state'<>'found' then raise exception 'Found status missing';end if;
 r:=public.navrang_locator('locator-stop',jsonb_build_object('eventId','O9KL3','requestId',gen_random_uuid()),staff_token);
 if r->>'onDuty'<>'false' or exists(select 1 from navrang_private.locator_fixes where checker_id=staff) then raise exception 'Stop retained location';end if;
 r:=public.navrang_locator('locator-fix',fix_payload||jsonb_build_object('sampleId',gen_random_uuid(),'capturedAt',clock_timestamp()),staff_token);
 if r->>'status'<>'409' then raise exception 'Late fix after Stop accepted';end if;
 r:=public.navrang_locator('locator-duty',jsonb_build_object('eventId','O9KL3','requestId',gen_random_uuid(),'durationMinutes',30),staff_token);
 r:=public.navrang_locator('locator-fix',fix_payload||jsonb_build_object('sampleId',gen_random_uuid(),'requestId',null,'capturedAt',clock_timestamp())-'requestId',staff_token);
 if r->>'saved'<>'true' then raise exception 'Voluntary share once without find-me failed';end if;
 update navrang_private.checkers set active=false where id=staff;
 if exists(select 1 from navrang_private.locator_fixes where checker_id=staff) or exists(select 1 from navrang_private.locator_duties where checker_id=staff) then raise exception 'Account revocation retained locator data';end if;
 r:=public.navrang_locator('locator-roster','{"eventId":"O9KL3"}',admin_token);
 if r->'items'<>'[]'::jsonb then raise exception 'Revoked volunteer leaked through roster';end if;
 -- Fresh family and legacy logout must physically retire duty/fix state, not
 -- wait for a later read or a still-unconfigured maintenance worker.
 update navrang_private.checkers set active=true where id=staff;
 delete from navrang_private.sessions where hash=staff_token;
 r:=public.navrang_gate('session-create',jsonb_build_object('hash',staff_token,'role','checker','checkerId',staff,'refreshHash',other_token,'installationId','locator-family-fixture'),'');
 family:=(r->>'refreshFamilyId')::uuid;
 if family is null then raise exception 'Locator renewable fixture not created';end if;
 r:=public.navrang_locator('locator-duty',jsonb_build_object('eventId','O9KL3','requestId',gen_random_uuid(),'durationMinutes',30),staff_token);
 r:=public.navrang_locator('locator-fix',jsonb_build_object('eventId','O9KL3','sampleId',gen_random_uuid(),'latitude',15.49,'longitude',73.82,'accuracy',20,'capturedAt',clock_timestamp()),staff_token);
 if r->>'saved'<>'true' then raise exception 'Renewable own fix failed';end if;
 perform navrang_private.revoke_session_family(family,'fixture-logout');
 if exists(select 1 from navrang_private.locator_fixes where checker_id=staff) or exists(select 1 from navrang_private.locator_duties where checker_id=staff) then raise exception 'Family logout retained physical locator state';end if;
 r:=public.navrang_locator('locator-consent',jsonb_build_object('eventId','O9KL3','requestId',gen_random_uuid(),'disclosureVersion',1,'location',true,'findMe',true),other_token);
 r:=public.navrang_locator('locator-duty',jsonb_build_object('eventId','O9KL3','requestId',gen_random_uuid(),'durationMinutes',30),other_token);
 r:=public.navrang_locator('locator-fix',jsonb_build_object('eventId','O9KL3','sampleId',gen_random_uuid(),'latitude',15.49,'longitude',73.82,'accuracy',20,'capturedAt',clock_timestamp()),other_token);
 if r->>'saved'<>'true' then raise exception 'Legacy retention fixture fix failed';end if;
 update navrang_private.locator_fixes set expires_at=clock_timestamp()-interval '1 second' where checker_id=other_staff;
 r:=public.navrang_locator('locator-view',jsonb_build_object('eventId','O9KL3','volunteerId',other_staff),admin_token);
 if r->'fix'<>'null'::jsonb or exists(select 1 from navrang_private.locator_fixes where checker_id=other_staff) then raise exception 'Expired coordinates retained or returned';end if;
 update navrang_private.locator_audit set at=clock_timestamp()-interval '25 hours';
 update navrang_private.locator_requests set created_at=clock_timestamp()-interval '25 hours',expires_at=clock_timestamp()-interval '24 hours 59 minutes';
 perform navrang_private.prune_locator();
 if exists(select 1 from navrang_private.locator_audit where at<clock_timestamp()-interval '24 hours') or exists(select 1 from navrang_private.locator_requests where expires_at<clock_timestamp()-interval '24 hours') then raise exception 'Metadata retention exceeded';end if;
 delete from navrang_private.sessions where hash=other_token;
 if exists(select 1 from navrang_private.locator_duties where checker_id=other_staff) then raise exception 'Legacy logout retained duty state';end if;
 r:=public.navrang_locator('locator-status','{"eventId":"wrong"}',other_token);
 if r->>'status'<>'400' then raise exception 'Cross-event locator accepted';end if;
 r:=public.navrang_locator('locator-status','{"eventId":"O9KL3","principal":"admin"}',admin_token);
 if r->>'status'<>'400' then raise exception 'Direct RPC actor injection accepted';end if;
 if has_function_privilege('anon','public.navrang_locator(text,jsonb,text)','execute') or has_table_privilege('authenticated','navrang_private.locator_fixes','select') then raise exception 'Location exposed to a public client role';end if;
 raise notice 'PASS: locator default off, explicit assignment, own consent/duty, targeting/replay/cooldown, private fix and revocation';
end;
$test$;
